        continue
    for line in c['error'].split('\n'):
        if 'Sort mismatch' in line:
            print(f"{c['id']}: {line.strip()[:200]}")
            break

# Check: how many crashes involve DeclareSort('Bool') or Bool = DeclareSort?
print("\n\n=== Anti-pattern prevalence ===")
custom_bool = 0
forall_sort = 0
